// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCollection, createUser, updateCollection, createCollectionTransfer, getCollectionMembers, getCollectionsList, deleteUser } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// NOTE ON CLEANUP: once ownership has moved, the former owner can no longer DELETE the
// collection (the collection route answers 401 for them). This test therefore removes the
// collection by deleting the successor account, which cascades it away. That the creator
// has no way to delete their own collection after a transfer is the defect under test.
test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, "tb-transfer-integrity");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-transfer-integrity");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    const formerOwnerId = getResponseValue(collectionsPostResponse, "response.ownerId");
    expect(formerOwnerId, 'ownerId').toBeGreaterThan(0);

    const usersPostResponse = await createUser(client, URL_localhost, headers, "TB Successor", "tbsuccessor", "tbsuccessor@example.com", "tbsuccessorpassword123");
    // An admin-authenticated create returns the narrow admin shape: id, username, email,
    // emailVerified, subscriptions, createdAt — no name field.
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toMatch(/^tbsuccessor-\d+$/);
    const successorUserId = getResponseValue(usersPostResponse, "response.id");
    expect(successorUserId, 'id').toBeGreaterThan(0);

    // Seed the membership row so the successor is an eligible transfer target.
    const collectionsCollectionsPutResponse = await updateCollection(client, URL_localhost, headers, collectionId, "tb-transfer-integrity", successorUserId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.ownerId"), 'ownerId before the transfer').toBe(formerOwnerId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members").length, 'members').toBe(1);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.userId"), 'members.0.userId').toBe(successorUserId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.1"), 'there is no second member').toBeNull();

    // Hand ownership to the member.
    const transferPostResponse = await createCollectionTransfer(client, URL_localhost, headers, collectionId, `{
        "toUserId": ${successorUserId}
    }`, 200);
    expect(getResponseValue(transferPostResponse, "response.id"), 'id').toBe(collectionId);
    expect(getResponseValue(transferPostResponse, "response.name"), 'name').toBe("tb-transfer-integrity");
    expect(getResponseValue(transferPostResponse, "response.ownerId"), 'ownerId is now the successor').toBe(successorUserId);

    // The owner-only members endpoint correctly follows ownership to the new owner.
    const membersGetResponse = await getCollectionMembers(client, URL_localhost, headers, collectionId, 403);
    expect(getResponseValue(membersGetResponse, "response"), 'response').toBe("Only the owner can manage members.");

    // The former owner must keep a route to the collection they handed over. transfer.ts:48
    // writes ownerId and nothing else: it grants the former owner no membership row, so
    // getCollections (which lists a collection for its owner OR its members) stops
    // returning it and the creator is locked out with no way back. This assertion is red
    // today and turns green once the transfer exchanges the owner and member rows the way
    // updateCollectionById.ts:64 models them.
    const collectionsGetResponse = await getCollectionsList(client, URL_localhost, headers);
    const stillReachable = getResponseValue(collectionsGetResponse, "response").filter((c: any) => c.id === collectionId);
    expect(stillReachable.length, 'the former owner still reaches the transferred collection').toBe(1);
    expect(stillReachable[0].ownerId, 'ownerId').toBe(successorUserId);
    expect(stillReachable[0].name, 'name').toBe("tb-transfer-integrity");

    // Deleting the successor cascades the transferred collection away.
    await deleteUser(client, URL_localhost, headers, successorUserId);
});
